// @port: Daqifi.Desktop.Configuration.FirewallConfiguration
public static class FirewallConfiguration
{
    private static readonly IAppLogger Logger = AppLogger.Instance;

    // Not upstream's "DAQiFi Desktop": that is the WPF app's rule, and sharing its name would make
    // a by-name cleanup (netsh, an IT script) take both apps' rules at once (#353).
    private const string RuleName = "DAQiFi";

    /// <summary>DAQiFi's UDP discovery port.</summary>
    internal const int DiscoveryPort = 30303;
    private static readonly WindowsFirewallWrapper FirewallHelper = new();
    private static readonly IMessageBoxService MessageBox = new AvaloniaMessageBoxService();

    // @port: Daqifi.Desktop.Configuration.FirewallConfiguration.InitializeFirewallRules
    public static void InitializeFirewallRules()
    {
        try
        {
            // The single source of truth for "is this process elevated" (AppDataPaths.IsElevated,
            // surfaced as App.IsElevated). The one caller already gates on the same value, so this
            // is a precondition re-check, not a second opinion — there used to be a second
            // implementation here (WindowsPrincipalAdminChecker) with byte-identical logic.
            if (!AppDataPaths.IsElevated)
            {
                // Avalonia message boxes are async-only; the informational prompt's result was
                // unused upstream, so fire-and-forget keeps this path synchronous.
                _ = MessageBox.ShowAsync(
                    "DAQiFi Desktop requires firewall permissions to discover devices on your network. " +
                    "Please run the application as administrator to automatically configure firewall rules, " +
                    "or manually add firewall rules for both private and public networks.",
                    "Firewall Configuration Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            var appPath = Process.GetCurrentProcess().MainModule?.FileName;

            // Validate application path
            if (!IsValidApplicationPath(appPath))
            {
                throw new InvalidOperationException("Invalid or missing application path for firewall rule creation.");
            }

            // Matched on the executable, not the rule name (#353). Upstream asked only "is there a
            // rule called DAQiFi Desktop?", but a rule is bound to one exe path: on a PC that has
            // the WPF app's rule, or a rule for another copy of this app, the answer was yes and
            // this copy never got one. Rules Windows created from its own "allow access" prompt
            // count too, whatever they are named.
            if (FirewallHelper.HasInboundUdpAllowRule(appPath, DiscoveryPort))
            {
                return;
            }

            FirewallHelper.CreateUdpRule(RuleName, appPath, DiscoveryPort);
        }
        catch (Exception ex)
        {
            Logger.Error(ex, "Failed to initialize firewall rules for DAQiFi Desktop");
            _ = MessageBox.ShowAsync(
                "Unable to configure firewall rules automatically. You may need to manually add firewall rules " +
                "for both private and public networks.\n\nError: " + ex.Message,
                "Firewall Configuration Error",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
        }
    }

    // @port: Daqifi.Desktop.Configuration.FirewallConfiguration.IsValidApplicationPath
    private static bool IsValidApplicationPath(string? path)
    {
        if (string.IsNullOrWhiteSpace(path))
            return false;

        try
        {
            // Check if file exists and has .exe extension
            return File.Exists(path) && Path.GetExtension(path).Equals(".exe", StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }
}

// @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper
public class WindowsFirewallWrapper
{
    private static readonly IAppLogger Logger = AppLogger.Instance;

    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.GetPolicy
    private static object GetPolicy()
    {
        var type = Type.GetTypeFromProgID("HNetCfg.FwPolicy2")
                   ?? throw new InvalidOperationException("Windows Firewall COM interface not available on this system");
        return Activator.CreateInstance(type)!;
    }

    /// <summary>
    /// Whether an enabled inbound rule already allows UDP traffic on <paramref name="port"/> to
    /// <paramref name="applicationPath"/>. A blank path answers <c>false</c> without touching
    /// the firewall.
    /// </summary>
    /// <exception cref="InvalidOperationException">The firewall could not be read.</exception>
    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.RuleExists
    // Downstream change (#353): replaces upstream's by-name RuleExists — see
    // FirewallConfiguration.InitializeFirewallRules for why.
    public bool HasInboundUdpAllowRule(string applicationPath, int port)
    {
        if (string.IsNullOrWhiteSpace(applicationPath))
            return false;

        object? policy = null;
        try
        {
            policy = GetPolicy();
            var rules = policy.GetType().InvokeMember("Rules",
                System.Reflection.BindingFlags.GetProperty, null, policy, null)!;
            // .NET marshals the collection's _NewEnum as an IEnumerator, not IEnumVARIANT.
            var enumerator = (System.Collections.IEnumerator)rules.GetType().InvokeMember("_NewEnum",
                System.Reflection.BindingFlags.GetProperty, null, rules, null)!;

            while (enumerator.MoveNext())
            {
                var rule = enumerator.Current;
                if (rule is null)
                    continue;

                try
                {
                    if (FirewallRuleMatch.AllowsInboundUdp(ReadRule(rule), applicationPath, port))
                        return true;
                }
                catch (Exception ex)
                {
                    // One unreadable rule (another program's, malformed) must not fail the whole
                    // check; at worst this app adds a rule it did not strictly need.
                    Logger.Warning(ex, "Skipped an unreadable firewall rule");
                }
                finally
                {
                    if (Marshal.IsComObject(rule))
                        Marshal.ReleaseComObject(rule);
                }
            }

            return false;
        }
        catch (Exception ex)
        {
            Logger.Error(ex, $"Failed to read firewall rules for application: {applicationPath}");
            throw new InvalidOperationException($"Failed to read firewall rules: {ex.Message}", ex);
        }
        finally
        {
            if (policy != null && Marshal.IsComObject(policy))
            {
                Marshal.ReleaseComObject(policy);
            }
        }
    }

    private static FirewallRuleInfo ReadRule(object rule)
    {
        object? Get(string name) => rule.GetType().InvokeMember(name,
            System.Reflection.BindingFlags.GetProperty, null, rule, null);

        return new FirewallRuleInfo(
            ApplicationName: Get("ApplicationName") as string,
            Direction: Convert.ToInt32(Get("Direction"), CultureInfo.InvariantCulture),
            Action: Convert.ToInt32(Get("Action"), CultureInfo.InvariantCulture),
            Enabled: Convert.ToBoolean(Get("Enabled"), CultureInfo.InvariantCulture),
            Protocol: Convert.ToInt32(Get("Protocol"), CultureInfo.InvariantCulture),
            LocalPorts: Get("LocalPorts") as string);
    }

    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.CreateUdpRule
    public void CreateUdpRule(string ruleName, string applicationPath, int port = 0)
    {
        ValidateInputs(ruleName, applicationPath);

        object? policy = null;
        object? rule = null;

        try
        {
            policy = GetPolicy();
            var ruleType = Type.GetTypeFromProgID("HNetCfg.FWRule")
                        ?? throw new InvalidOperationException("Windows Firewall Rule COM interface not available");
            rule = Activator.CreateInstance(ruleType)!;

            // Set rule properties using reflection for better error handling
            SetRuleProperty(rule, "Name", ruleName);
            SetRuleProperty(rule, "ApplicationName", applicationPath);
            SetRuleProperty(rule, "Protocol", 17); // UDP
            SetRuleProperty(rule, "Direction", 1); // Inbound
            SetRuleProperty(rule, "Action", 1);    // Allow
            SetRuleProperty(rule, "Enabled", true);
            SetRuleProperty(rule, "Profiles", 7);  // Domain|Private|Public

            // Set specific port if provided
            if (port is > 0 and <= 65535)
            {
                SetRuleProperty(rule, "LocalPorts", port.ToString(CultureInfo.InvariantCulture));
            }

            // Add rule to policy
            var rules = policy.GetType().InvokeMember("Rules",
                System.Reflection.BindingFlags.GetProperty, null, policy, null);
            rules.GetType().InvokeMember("Add",
                System.Reflection.BindingFlags.InvokeMethod, null, rules, [rule]);
        }
        catch (Exception ex)
        {
            Logger.Error(ex, $"Failed to create firewall rule '{ruleName}' for application: {applicationPath}");
            throw new InvalidOperationException($"Failed to create firewall rule '{ruleName}': {ex.Message}", ex);
        }
        finally
        {
            if (rule != null && Marshal.IsComObject(rule))
            {
                Marshal.ReleaseComObject(rule);
            }
            if (policy != null && Marshal.IsComObject(policy))
            {
                Marshal.ReleaseComObject(policy);
            }
        }
    }

    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.SetRuleProperty
    private static void SetRuleProperty(object rule, string propertyName, object value)
    {
        try
        {
            rule.GetType().InvokeMember(propertyName,
                System.Reflection.BindingFlags.SetProperty, null, rule, [value]);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException($"Failed to set firewall rule property '{propertyName}': {ex.Message}", ex);
        }
    }

    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.IsValidRuleName
    private static bool IsValidRuleName(string ruleName)
    {
        if (string.IsNullOrWhiteSpace(ruleName))
            return false;

        // Check for potentially dangerous characters that could be used for injection
        var invalidChars = new char[] { '<', '>', '|', '&', ';', '$', '`', '\0', '\r', '\n' };
        return !ruleName.Any(c => invalidChars.Contains(c)) && ruleName.Length <= 255;
    }

    // @port: Daqifi.Desktop.Configuration.WindowsFirewallWrapper.ValidateInputs
    private static void ValidateInputs(string ruleName, string applicationPath)
    {
        if (!IsValidRuleName(ruleName))
            throw new ArgumentException("Invalid firewall rule name. Rule names must be non-empty, under 256 characters, and not contain special characters.", nameof(ruleName));

        if (string.IsNullOrWhiteSpace(applicationPath))
            throw new ArgumentException("Application path cannot be null or empty.", nameof(applicationPath));

        if (!File.Exists(applicationPath))
            throw new ArgumentException($"Application file not found: {applicationPath}", nameof(applicationPath));

        if (!Path.GetExtension(applicationPath).Equals(".exe", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("Application path must point to an executable (.exe) file.", nameof(applicationPath));
    }
}
